MATCH (source:PlantItem)-[:send_to*1..]->(target:PlantItem {tag: 'P-51101B'})
WHERE NOT EXISTS {
  MATCH (:PlantItem)-[:send_to]->(source)
}
RETURN DISTINCT source.tag AS tag
ORDER BY tag

MATCH (pump:PlantItem {tag: "P-26901A"})-[:send_to*1..]->(valve:PlantItem)
WHERE valve:OperatedValve
  AND NOT EXISTS {
    MATCH (pump)-[:send_to*1..]->(earlier:PlantItem)-[:send_to*1..]->(valve)
    WHERE earlier:OperatedValve
  }
  AND EXISTS {
    MATCH (valve)-[:send_to*1..]->(equipment:Equipment)
  }
RETURN DISTINCT valve.tag AS tag

